import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Decisions","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Decisions"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/adr/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/adr/"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/docs/adr"}},"headers":[],"relativePath":"adr/index.md","filePath":"adr/index.md","lastUpdated":1794431921000}`),a={name:`adr/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to “Decisions”">​</a></h1><ul><li><p><strong><a href="./0001-entity-stat-authority.html">Which edition decides an entity stat</a></strong></p><p>Bedrock&#39;s entity definitions and Java Edition&#39;s attribute suppliers publish 438 of the same stats for the same entity, and they disagree on 151 of them.</p></li><li><p><strong><a href="./0002-chunk-generation-architecture.html">Generate a chunk through a status ladder, not a 3 by 3 region</a></strong></p><p><code>DataDrivenGenerator.generateChunk</code> builds a 3 by 3 region, generates terrain for nine chunks, decorates the center, extracts one chunk and serializes the whole body behind one promise, at 1572 ms per chunk.</p></li><li><p><strong><a href="./0003-declarative-wire-layouts.html">Describe a packet&#39;s wire layout as data, once, in the protocol package</a></strong></p><p>A packet whose layout changed at a protocol version is today a sibling class: <code>AnimatePacket2225 extends AnimatePacket</code>, overriding <code>encodePayload</code>/<code>decodePayload</code>, substituted per session by <code>prepareOutbound</code> with an <code>Object.assign</code> copy.</p></li><li><p><strong><a href="./0004-data-driven-dimensions.html">Describe a dimension as a Java level stem, and keep one <code>World</code> per dimension</a></strong></p><p>Every world this server loads is the Overworld.</p></li><li><p><strong><a href="./0005-generation-host-process.html">Run chunk generation in a host process, and keep the in-process pool as the fallback</a></strong></p><p>Generation workers are threads of the server process.</p></li><li><p><strong><a href="./0006-replay-determinism-contract.html">The simulation replays identically at any host speed</a></strong></p><p>Given an initial-state manifest, the random state and an ordered inbound packet trace, a replay produces the same per-tick replay digest series and the same outbound packet digests on every run, however fast the host is.</p></li><li><p><strong><a href="./0007-one-entity-index-visible-on-write.html">One entity index, and a position write is visible to the next query</a></strong></p><p>The world kept two entity indexes with opposite rules.</p></li><li><p><strong><a href="./0008-one-entity-model.html">One entity model, with players and items in the same store</a></strong></p><p>Every entity in a world lives in one entity store, and every entity has the shape a data-driven mob has today: a reference to a resolved entity type, the component state of an <code>EntityInstance</code>, and a body.</p></li><li><p><strong><a href="./0009-external-inputs-enter-once-per-tick.html">External inputs enter a world once per tick and are recorded</a></strong></p><p>Anything outside a world&#39;s tick reaches that world as an input: inbound packets, chunk completions, and the results of offloaded work such as pathfinding, lighting or encoding.</p></li><li><p><strong><a href="./0010-no-barrel-files.html">No barrel files, and each package exports an explicit list of modules</a></strong></p><p>A barrel is a module that re-exports another module&#39;s symbols, whether or not it also declares its own.</p></li><li><p><strong><a href="./0011-a-world-exchanges-only-plain-data.html">A world exchanges only plain data with everything outside it</a></strong></p><p>Five rules keep a world&#39;s simulation separable from the code around it.</p></li><li><p><strong><a href="./0012-the-change-log-is-the-history.html">The change log is a world&#39;s history, complete and invertible</a></strong></p><p>The simulation&#39;s change log is the history of a world.</p></li><li><p><strong><a href="./0013-vetoable-actions-are-staged.html">Vetoable actions run as intent, guard, compute and commit</a></strong></p><p>Every action that can be vetoed or modified runs in four stages.</p></li><li><p><strong><a href="./0014-handlers-share-a-shape-and-run-in-the-input-step.html">Packet handlers share one shape in both directions, and serverbound handlers run in the input step</a></strong></p><p>Packet handlers register by packet name and session phase, in one shape defined in <code>@jsprismarine/protocol</code> that the server and the client package both use.</p></li><li><p><strong><a href="./0015-a-tick-is-a-fixed-sequence-of-synchronous-phases.html">A tick is a fixed sequence of synchronous phases</a></strong></p><p>A world&#39;s tick runs these phases in this order.</p></li><li><p><strong><a href="./0016-replication-reads-the-change-log.html">Replication reads the change log after the tick</a></strong></p><p>Replication is a read-only stage that runs after a tick closes.</p></li><li><p><strong><a href="./0017-one-lifecycle-event-bus.html">One lifecycle event bus replaces the legacy emitter</a></strong></p><p>The change log (<a href="/pr-preview/pr-2948/adr/0012-the-change-log-is-the-history.html">ADR 0012</a>) and the staged guards (<a href="/pr-preview/pr-2948/adr/0013-vetoable-actions-are-staged.html">ADR 0013</a>) replace the simulation events.</p></li><li><p><strong><a href="./0018-a-save-is-a-snapshot-of-one-tick-boundary.html">A save is a snapshot of one tick boundary</a></strong></p><p>A save pass writes the authoritative state of one tick boundary of a level, called the save cut, for every dimension the level holds, and commits it as one atomic write.</p></li></ul></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};